mapper.select:
SELECT DISTINCT d.* FROM database_resource d JOIN database_data_type r ON r.database_id=d.id JOIN data_type t ON t.id=r.data_type_id WHERE d.is_visible=TRUE AND d.status='ENABLED' AND t.code=#{type} AND (
CONCAT(';',LOWER(COALESCE(d.db_id,'')),';') LIKE CONCAT('%;',LOWER(#{dbId}),';%')
) ORDER BY d.id

SELECT r.database_id AS database_id,t.code AS data_type_code FROM database_data_type r JOIN data_type t ON t.id=r.data_type_id WHERE t.is_visible=TRUE AND t.status='ENABLED' AND r.database_id IN
#{databaseId}
ORDER BY t.sort_order,t.id,r.database_id

SELECT t.*,r.database_id AS relation_database_id,r.relation_type,r.relation_basis FROM online_tool t JOIN database_tool r ON r.tool_id=t.id WHERE t.is_visible=TRUE AND t.status='ENABLED' AND r.database_id IN
#{databaseId}
ORDER BY r.database_id,t.id
